/* HEXA BATTLEGROUNDS upgrade — PART 2 OF 6. Only for databases that already ran setup part-01…; run in order. Safe to re-run. */ create or replace function _start_instance( p_team uuid, p_template text, p_location text default null, p_battle uuid default null, p_airdrop uuid default null, p_sync uuid default null, p_deadline timestamptz default null, p_partner uuid default null ) returns uuid language plpgsql as $$ declare t teams; mt mission_templates; v_id uuid; v_partner uuid; v_key text; v_seed int; v_pct int; begin select * into t from teams where id = p_team for update; select * into mt from mission_templates where id = p_template; if mt.id is null then raise exception 'NO_TEMPLATE'; end if; select mission_seed into v_seed from events where id = t.event_id; v_pct := greatest(20, least(300, _cfg(t.event_id, 'mission_time_pct'))); if mt.relay then v_partner := p_partner; if v_partner is null then select x.id into v_partner from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id order by md5(v_seed::text || t.id::text || x.id::text || t.mission_counter::text) limit 1; end if; v_key := _codeword(v_seed::text || t.id::text || t.mission_counter::text); end if; insert into mission_instances(arena_id, team_id, template_id, template_version, kind, location_id, battle_id, airdrop_id, sync_round_id, attempts_left, deadline, partner_team_id, relay_key, fallback_at) values (t.arena_id, t.id, mt.id, mt.version, mt.kind, coalesce(p_location, t.location_id), p_battle, p_airdrop, p_sync, mt.attempts, coalesce(p_deadline, now() + _secs(mt.time_limit * v_pct / 100.0)), v_partner, v_key, case when mt.relay and v_partner is not null then now() + _secs(_cfg(t.event_id, 'intel_fallback')) when mt.relay then now() end) returning id into v_id; update teams set mission_counter = mission_counter + 1, visit_missions = visit_missions + case when mt.kind in ('mission', 'relay') then 1 else 0 end where id = t.id; perform _ping_team(t.id, 'mission'); if v_partner is not null then perform _ping_team(v_partner, 'intel'); end if; return v_id; end $$; create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; end $$;
